insert into public.equipment_pages (href, title, description, breadcrumb, hero_image, hero_alt, overview_image, overview_image_alt, overview_heading, overview, systems, engagement_heading, engagement_body, platforms_heading, platforms, architectures, application_ids, closing) values ('/equipment-options/adhesives-sealants', 'Adhesives & Sealants', 'Precision metering, mixing, dispensing, and validation of advanced bonding materials for industrial manufacturing.', '[{"label":"Home","href":"/"},{"label":"Equipment Options","href":"/equipment-options"},{"label":"Adhesives & Sealants"}]'::jsonb, '/images/equipment-hero.webp', 'Adhesive dispensing equipment on a production line', '/images/adhesive-bonding.jpg', 'Adhesive bonding on a manufactured assembly', 'Precision Metering, Mixing, and Structural Bonding Automation', '["Adhesives and sealant systems are critical to modern manufacturing, where mechanical fastening alone cannot meet structural, environmental, or weight requirements. These systems govern the precision metering, mixing, dispensing, and validation of advanced bonding materials, ensuring structural integrity, repeatability, and process reliability across high-performance production environments.","Our engineered systems support single-component and multi-component adhesive platforms, integrating material conditioning, robotic dispensing, and automated inspection into fully controlled production processes. From aerospace composite bonding to automotive glazing systems, precision adhesive application is fundamental to product performance."]'::jsonb, '[{"title":"Single Component Systems","description":"Dispensing valves, metering valves, pump & pressure packages for 1K adhesives","href":"/equipment-options/adhesives-sealants/single-component","categorySlug":"single-component"},{"title":"Two Component Systems (2K)","description":"Gear metering, piston metering, shot metering, mixing valves, LSR processing","href":"/equipment-options/adhesives-sealants/two-component","categorySlug":"two-component"},{"title":"Tooling Paste & Seamless Molding","description":"Eldo-Mix 401T, GP 401 TPD for precision tooling and modeling applications","href":"/equipment-options/adhesives-sealants/tooling-paste-seamless-modeling-paste","categorySlug":"tooling-paste"},{"title":"SMC/IMC Molding","description":"IMC Coatec metering systems for sheet molding and in-mold coating applications","href":"/equipment-options/adhesives-sealants/smc-imc-molding","categorySlug":"smc-imc-molding"},{"title":"Putty & Paste Systems","description":"GP 401 APD, CF Versa, and GP 401 TPD for high-viscosity paste dispensing","href":"/equipment-options/adhesives-sealants/putty-paste","categorySlug":"putty-paste"}]'::jsonb, 'Ready to Engineer Your Adhesive System?', 'Kirkco supports confidential engineering engagements under NDA. Discuss your application requirements with our team and receive a system architecture tailored to your process.', 'Technical Platforms', '[{"heading":"Adhesive Chemistry Platforms","items":["Two-component epoxy structural adhesives","Polyurethane structural adhesives","Silicone sealants and gasketing materials","Methacrylate adhesives (MMA)","Liquid Silicone Rubber (LSR) processing systems","Filled and spacer-loaded structural adhesives"]},{"heading":"Metering & Mixing Technology","items":["Servo-driven piston metering systems","Precision gear metering assemblies","Progressive cavity pumps for high-filler systems","Static mixing tubes","Dynamic mixing heads","High-pressure impingement mixing (specialized applications)"]}]'::jsonb, '[{"heading":"Single-Component & Multi-Component System Architecture","groups":[{"title":"Single-Component Systems","links":[{"label":"Dispensing Valves","href":"/equipment-options/adhesives-sealants/single-component"},{"label":"Metering Valves","href":"/equipment-options/adhesives-sealants/single-component"},{"label":"Pumps & Packages","href":"/equipment-options/adhesives-sealants/single-component"}]},{"title":"Multi-Component Systems","links":[{"label":"Gear Metering","href":"/equipment-options/adhesives-sealants/two-component"},{"label":"LSR Processing Equipment","href":"/equipment-options/adhesives-sealants/two-component"},{"label":"Shot Metering","href":"/equipment-options/adhesives-sealants/two-component"},{"label":"Mixing Valves","href":"/equipment-options/adhesives-sealants/two-component"},{"label":"Piston Metering","href":"/equipment-options/adhesives-sealants/two-component"},{"label":"Progressive Cavity Metering","href":"/equipment-options/adhesives-sealants/two-component"}]}]},{"heading":"Chemistry System Architecture","groups":[{"title":"Tooling Paste","links":[{"label":"Eldo-Mix 401T & Tooling Mix","href":"/equipment-options/adhesives-sealants/tooling-paste-seamless-modeling-paste"},{"label":"GP 401 TPD","href":"/equipment-options/adhesives-sealants/tooling-paste-seamless-modeling-paste"}]},{"title":"SMC / IMC Molding","links":[{"label":"IMC Coatec Metering","href":"/equipment-options/adhesives-sealants/smc-imc-molding"}]},{"title":"Putty & Paste","links":[{"label":"GP 401 APD & CF Versa","href":"/equipment-options/adhesives-sealants/putty-paste"},{"label":"GP 401 TPD","href":"/equipment-options/adhesives-sealants/putty-paste"}]}]}]'::jsonb, '["adhesives-quality-framework","industrial-adhesive-dispensing"]'::jsonb, 'Precision Metering System for Accuracy in your Process');